## Estimated savings

~25 lines saved using a macro:

```rust
macro_rules! corpus_test {
    ($name:ident, $corpus:expr, $min_files:expr, $min_functions:expr) => {
        #[test]
        fn $name() {
            if let Some(dir) = corpus_dir($corpus) {
                let (files, functions) = analyze_corpus(&dir);
                eprintln!("{}: {} files, {} functions", $corpus, files, functions);
                assert!(files > $min_files, "expected >{} files, got {}", $min_files, files);
                assert!(functions > $min_functions, "expected >{} functions, got {}", $min_functions, functions);
            } else {
                eprintln!("Skipping {} corpus (not found). Run ./scripts/bootstrap-corpora.sh", $corpus);
            }
        }
    };
}

corpus_test!(test_corpus_requests, "requests", 10, 50);
corpus_test!(test_corpus_flask, "flask", 10, 50);
corpus_test!(test_corpus_rich, "rich", 20, 200);
```

